// dashboard-fix.js
const fs=require('fs');const path=require('path');const{execSync}=require('child_process');
const files={"frontend/src/components/ui/CreditWallet.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Zap, Plus, TrendingUp, AlertTriangle, X, Check } from \"lucide-react\";\nimport { useCreditsStore, CREDIT_COSTS } from \"../../store/credits.store\";\nimport { api } from \"../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport { useTheme } from \"../layout/DashboardLayout\";\n\nconst TOP_UP_PACKS = [\n  { id: \"starter\",    amount: 500,   price: 1500,   label: \"Starter\",    popular: false },\n  { id: \"growth\",     amount: 2000,  price: 5000,   label: \"Growth\",     popular: true  },\n  { id: \"pro\",        amount: 5000,  price: 10000,  label: \"Pro\",        popular: false },\n  { id: \"unlimited\",  amount: 15000, price: 25000,  label: \"Unlimited\",  popular: false },\n];\n\nexport function CreditBadge({ compact = false }: { compact?: boolean }) {\n\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const T = {\n    text:   isDark ? \"#F0ECFF\"                : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\"  : \"rgba(19,13,46,0.5)\",\n    faint:  isDark ? \"rgba(240,236,255,0.25)\" : \"rgba(19,13,46,0.3)\",\n    card:   isDark ? \"#181230\" : \"#ffffff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.09)\",\n    bg:     isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const { balance, monthlyLimit } = useCreditsStore();\n  const pct = Math.round((balance / monthlyLimit) * 100);\n  const isLow = pct <= 20;\n  const isCritical = pct <= 5;\n\n  const color = isCritical ? \"#EF4444\" : isLow ? \"#F59E0B\" : \"#10B981\";\n  const bg    = isCritical ? \"rgba(239,68,68,0.1)\" : isLow ? \"rgba(245,158,11,0.1)\" : \"rgba(107,53,232,0.1)\";\n\n  if (compact) {\n    return (\n      <div style={{ display: \"flex\", alignItems: \"center\", gap: 5, padding: \"4px 10px\", borderRadius: 20, background: bg, border: `1px solid ${color}30` }}>\n        <Zap size={11} color={color} />\n        <span style={{ fontSize: 11, fontWeight: 700, color }}>{balance.toLocaleString()}</span>\n      </div>\n    );\n  }\n\n  return (\n    <div style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n      <Zap size={13} color={color} />\n      <div style={{ flex: 1 }}>\n        <div style={{ display: \"flex\", justifyContent: \"space-between\", marginBottom: 3 }}>\n          <span style={{ fontSize: 11, fontWeight: 600, color: T.text }}>Credits</span>\n          <span style={{ fontSize: 11, fontWeight: 700, color }}>{balance.toLocaleString()} / {monthlyLimit.toLocaleString()}</span>\n        </div>\n        <div style={{ height: 4, borderRadius: 99, background: T.faint, overflow: \"hidden\" }}>\n          <motion.div\n            initial={{ width: 0 }}\n            animate={{ width: `${pct}%` }}\n            transition={{ duration: 0.8, ease: \"easeOut\" }}\n            style={{ height: \"100%\", borderRadius: 99, background: color }}\n          />\n        </div>\n      </div>\n    </div>\n  );\n}\n\nexport function CreditCost({ feature, children }: { feature: keyof typeof CREDIT_COSTS; children?: React.ReactNode }) {\n  const { balance } = useCreditsStore();\n  const cost = CREDIT_COSTS[feature];\n  const canAfford = balance >= cost;\n\n  return (\n    <div style={{ display: \"flex\", alignItems: \"center\", gap: 6 }}>\n      {children}\n      <span style={{ fontSize: 11, fontWeight: 600, color: canAfford ? \"#A78BFA\" : \"#EF4444\", display: \"flex\", alignItems: \"center\", gap: 3 }}>\n        <Zap size={10} />\n        {cost} credits\n        {!canAfford && <AlertTriangle size={10} color=\"#EF4444\" />}\n      </span>\n    </div>\n  );\n}\n\nexport function TopUpModal({ onClose }: { onClose: () => void }) {\n  const [loading, setLoading] = useState<string | null>(null);\n  const { setBalance, balance } = useCreditsStore();\n\n  const handleTopUp = async (pack: typeof TOP_UP_PACKS[0]) => {\n    setLoading(pack.id);\n    try {\n      const res = await api.post(\"/billing/credits/topup\", { packId: pack.id });\n      const url = res.data?.data?.authorizationUrl;\n      if (url) {\n        window.location.href = url;\n      } else {\n        // Demo mode - just add credits\n        setBalance(balance + pack.amount);\n        toast.success(`Added ${pack.amount.toLocaleString()} credits!`);\n        onClose();\n      }\n    } catch {\n      toast.error(\"Top-up failed - backend offline\");\n    } finally {\n      setLoading(null);\n    }\n  };\n\n  return (\n    <div style={{ position: \"fixed\", inset: 0, zIndex: 9999, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", padding: 16, background: \"rgba(0,0,0,0.7)\", backdropFilter: \"blur(8px)\" }}\n      onClick={e => e.target === e.currentTarget && onClose()}>\n      <motion.div initial={{ opacity: 0, scale: 0.95, y: 16 }} animate={{ opacity: 1, scale: 1, y: 0 }}\n        style={{ width: \"100%\", maxWidth: 420, borderRadius: 24, background: T.card, border: \"1px solid rgba(255,255,255,0.08)\", overflow: \"hidden\" }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", padding: \"20px 24px\", borderBottom: \"1px solid rgba(255,255,255,0.06)\" }}>\n          <div>\n            <h2 style={{ fontSize: 16, fontWeight: 800, color: \"#fff\", marginBottom: 2 }}>Top Up Credits</h2>\n            <p style={{ fontSize: 12, color: T.muted }}>Credits never expire. Use for KIRO, images, videos.</p>\n          </div>\n          <button onClick={onClose} style={{ color: T.muted, background: \"none\", border: \"none\", cursor: \"pointer\" }}><X size={18} /></button>\n        </div>\n\n        <div style={{ padding: 24, display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 12 }}>\n          {TOP_UP_PACKS.map(pack => (\n            <button key={pack.id} onClick={() => handleTopUp(pack)} disabled={!!loading}\n              style={{ padding: \"16px\", borderRadius: 16, border: `1px solid ${pack.popular ? \"rgba(107,53,232,0.5)\" : T.faint}`, background: pack.popular ? \"rgba(107,53,232,0.1)\" : T.faint, cursor: \"pointer\", textAlign: \"left\", position: \"relative\", opacity: loading ? 0.6 : 1 }}>\n              {pack.popular && <span style={{ position: \"absolute\", top: -8, right: 8, fontSize: 9, fontWeight: 700, padding: \"2px 8px\", borderRadius: 99, background: \"#6B35E8\", color: \"#fff\", letterSpacing: \"0.05em\", textTransform: \"uppercase\" }}>Popular</span>}\n              {loading === pack.id\n                ? <div style={{ height: 40, display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                    <motion.div animate={{ rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: \"linear\" }}><Zap size={16} color=\"#8B5CF6\" /></motion.div>\n                  </div>\n                : <>\n                    <p style={{ fontSize: 20, fontWeight: 900, color: \"#fff\", marginBottom: 2 }}>{pack.amount.toLocaleString()}</p>\n                    <p style={{ fontSize: 11, color: T.muted, marginBottom: 10 }}>credits</p>\n                    <p style={{ fontSize: 15, fontWeight: 800, color: \"#A78BFA\" }}>₦{pack.price.toLocaleString()}</p>\n                  </>\n              }\n            </button>\n          ))}\n        </div>\n\n        <div style={{ padding: \"0 24px 24px\" }}>\n          <div style={{ padding: \"12px 16px\", borderRadius: 12, background: \"rgba(107,53,232,0.06)\", border: \"1px solid rgba(107,53,232,0.15)\", fontSize: 12, color: T.muted, lineHeight: 1.6 }}>\n            Top-up credits roll over forever. Monthly plan credits reset each billing date. KIRO uses 1 credit per message.\n          </div>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n\nexport default function CreditWallet() {\n  const { balance, plan, monthlyLimit, usedThisMonth } = useCreditsStore();\n  const [showTopUp, setShowTopUp] = useState(false);\n  const pct = Math.round((balance / monthlyLimit) * 100);\n  const isLow = pct <= 20;\n\n  return (\n    <>\n      <div style={{ padding: \"14px 16px\", borderRadius: 16, background: \"rgba(107,53,232,0.08)\", border: \"1px solid rgba(107,53,232,0.2)\" }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 10 }}>\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 6 }}>\n            <Zap size={14} color=\"#8B5CF6\" />\n            <span style={{ fontSize: 13, fontWeight: 700, color: \"#fff\" }}>KIRO Credits</span>\n          </div>\n          <button onClick={() => setShowTopUp(true)}\n            style={{ display: \"flex\", alignItems: \"center\", gap: 4, padding: \"4px 10px\", borderRadius: 8, border: \"1px solid rgba(107,53,232,0.4)\", background: \"rgba(107,53,232,0.12)\", color: \"#A78BFA\", fontSize: 11, fontWeight: 600, cursor: \"pointer\" }}>\n            <Plus size={10} /> Top Up\n          </button>\n        </div>\n\n        <div style={{ display: \"flex\", alignItems: \"baseline\", gap: 4, marginBottom: 8 }}>\n          <span style={{ fontSize: 24, fontWeight: 900, color: isLow ? \"#F59E0B\" : \"#fff\" }}>{balance.toLocaleString()}</span>\n          <span style={{ fontSize: 12, color: T.faint }}>/ {monthlyLimit.toLocaleString()} this month</span>\n        </div>\n\n        <div style={{ height: 5, borderRadius: 99, background: T.faint, overflow: \"hidden\", marginBottom: 8 }}>\n          <motion.div initial={{ width: 0 }} animate={{ width: `${pct}%` }} transition={{ duration: 0.8 }}\n            style={{ height: \"100%\", borderRadius: 99, background: isLow ? (pct <= 5 ? \"#EF4444\" : \"#F59E0B\") : \"#6B35E8\" }} />\n        </div>\n\n        {isLow && (\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 5, fontSize: 11, color: pct <= 5 ? \"#F87171\" : \"#FCD34D\" }}>\n            <AlertTriangle size={11} />\n            {pct <= 5 ? \"Almost out! Top up to keep KIRO running.\" : \"Running low on credits.\"}\n          </div>\n        )}\n      </div>\n\n      <AnimatePresence>\n        {showTopUp && <TopUpModal onClose={() => setShowTopUp(false)} />}\n      </AnimatePresence>\n    </>\n  );\n}\n","frontend/src/components/ui/PlanGate.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Zap, X, ArrowRight, Crown, Lock } from \"lucide-react\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport Link from \"next/link\";\nimport { useTheme } from \"../layout/DashboardLayout\";\n\ntype Feature =\n  | \"products\"   // Free: 20, Growth+: unlimited\n  | \"stores\"     // Free+Growth: 1, Pro: unlimited\n  | \"kiro\"       // Free: 10/day, Growth+: unlimited\n  | \"analytics\"  // Free: basic, Growth+: full\n  | \"domain\"     // Free: no, Growth+: yes\n  | \"branding\"   // Free: required, Growth+: removable\n  | \"campaigns\"  // Pro only\n  | \"loyalty\"    // Pro only\n  | \"whatsapp\"   // Pro only\n  | \"api\"        // Pro only\n  | \"staff\";     // Pro only: 3 accounts\n\nconst PLAN_REQUIREMENTS: Record<Feature, \"FREE\" | \"GROWTH\" | \"PRO\"> = {\n  products:  \"GROWTH\",\n  stores:    \"PRO\",\n  kiro:      \"GROWTH\",\n  analytics: \"GROWTH\",\n  domain:    \"GROWTH\",\n  branding:  \"GROWTH\",\n  campaigns: \"PRO\",\n  loyalty:   \"PRO\",\n  whatsapp:  \"PRO\",\n  api:       \"PRO\",\n  staff:     \"PRO\",\n};\n\nconst UPGRADE_COPY: Record<Feature, { title: string; desc: string; cta: string }> = {\n  products:  { title: \"Upgrade to add more products\", desc: \"You've hit the 20 product limit on your free plan. Growth gives you unlimited products.\", cta: \"Upgrade to Growth - ₦9,500/mo\" },\n  stores:    { title: \"Multiple stores on Pro\", desc: \"Run unlimited stores on Pro. Your Growth plan includes 1 store.\", cta: \"Upgrade to Pro - ₦25,000/mo\" },\n  kiro:      { title: \"Unlimited KIRO on Growth\", desc: \"You've used your 10 free KIRO messages today. Upgrade for unlimited chat.\", cta: \"Upgrade to Growth - ₦9,500/mo\" },\n  analytics: { title: \"Full analytics on Growth\", desc: \"See LTV, cohorts, and revenue attribution with a Growth plan.\", cta: \"Upgrade to Growth - ₦9,500/mo\" },\n  domain:    { title: \"Custom domain on Growth\", desc: \"Remove the dropos.io subdomain and use your own domain.\", cta: \"Upgrade to Growth - ₦9,500/mo\" },\n  branding:  { title: \"Remove DropOS branding\", desc: \"Show your brand, not ours. Available on Growth and above.\", cta: \"Upgrade to Growth - ₦9,500/mo\" },\n  campaigns: { title: \"Email campaigns on Pro\", desc: \"Send broadcast emails to your customer segments.\", cta: \"Upgrade to Pro - ₦25,000/mo\" },\n  loyalty:   { title: \"Loyalty programme on Pro\", desc: \"Keep customers coming back with points and rewards.\", cta: \"Upgrade to Pro - ₦25,000/mo\" },\n  whatsapp:  { title: \"WhatsApp Commerce on Pro\", desc: \"KIRO handles all customer WhatsApp messages automatically, 24/7.\", cta: \"Upgrade to Pro - ₦25,000/mo\" },\n  api:       { title: \"API access on Pro\", desc: \"Build on top of DropOS with full API access.\", cta: \"Upgrade to Pro - ₦25,000/mo\" },\n  staff:     { title: \"Staff accounts on Pro\", desc: \"Add up to 3 team members to manage your store.\", cta: \"Upgrade to Pro - ₦25,000/mo\" },\n};\n\nfunction getPlanLevel(plan: string): number {\n  if (plan === \"PRO\")    return 3;\n  if (plan === \"GROWTH\") return 2;\n  return 1; // FREE\n}\n\nfunction meetsRequirement(userPlan: string, required: string): boolean {\n  return getPlanLevel(userPlan) >= getPlanLevel(required);\n}\n\ninterface PlanGateProps {\n  feature:   Feature;\n  children:  React.ReactNode;\n  fallback?: React.ReactNode;\n  silent?:   boolean; // just hide, no modal\n}\n\nexport function PlanGate({ feature, children, fallback, silent }: PlanGateProps) {\n\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const T = {\n    text:   isDark ? \"#F0ECFF\"                : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\"  : \"rgba(19,13,46,0.5)\",\n    faint:  isDark ? \"rgba(240,236,255,0.25)\" : \"rgba(19,13,46,0.3)\",\n    card:   isDark ? \"#181230\" : \"#ffffff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.09)\",\n    bg:     isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const user    = useAuthStore(s => s.user);\n  const plan    = user?.subscription?.plan || \"FREE\";\n  const required = PLAN_REQUIREMENTS[feature];\n\n  if (meetsRequirement(plan, required)) return <>{children}</>;\n  if (silent) return fallback ? <>{fallback}</> : null;\n\n  return (\n    <>\n      {fallback || (\n        <div style={{ opacity: 0.4, pointerEvents: \"none\", filter: \"grayscale(0.5)\" }}>\n          {children}\n        </div>\n      )}\n      <UpgradePrompt feature={feature} requiredPlan={required} />\n    </>\n  );\n}\n\nexport function UpgradePrompt({ feature, requiredPlan, inline = false }: { feature: Feature; requiredPlan: string; inline?: boolean }) {\n  const [dismissed, setDismissed] = useState(false);\n  const copy = UPGRADE_COPY[feature];\n  const color = requiredPlan === \"PRO\" ? \"#F59E0B\" : \"#8B5CF6\";\n  const bg    = requiredPlan === \"PRO\" ? \"rgba(245,158,11,0.08)\" : \"rgba(107,53,232,0.08)\";\n\n  if (dismissed && inline) return null;\n\n  if (inline) {\n    return (\n      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}\n        style={{ padding: \"14px 16px\", borderRadius: 14, background: bg, border: `1px solid ${color}30`, display: \"flex\", alignItems: \"center\", gap: 12 }}>\n        <div style={{ width: 32, height: 32, borderRadius: 10, background: `${color}15`, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}>\n          {requiredPlan === \"PRO\" ? <Crown size={14} color={color} /> : <Zap size={14} color={color} />}\n        </div>\n        <div style={{ flex: 1 }}>\n          <p style={{ fontSize: 13, fontWeight: 700, color: \"#fff\", marginBottom: 2 }}>{copy.title}</p>\n          <p style={{ fontSize: 12, color: T.muted, lineHeight: 1.5 }}>{copy.desc}</p>\n        </div>\n        <Link href=\"/dashboard/billing\">\n          <button style={{ display: \"flex\", alignItems: \"center\", gap: 6, padding: \"8px 14px\", borderRadius: 10, border: \"none\", background: `linear-gradient(135deg,${color},${color}99)`, color: \"#fff\", fontSize: 12, fontWeight: 700, cursor: \"pointer\", whiteSpace: \"nowrap\" }}>\n            Upgrade <ArrowRight size={11} />\n          </button>\n        </Link>\n        <button onClick={() => setDismissed(true)} style={{ color: T.faint, background: \"none\", border: \"none\", cursor: \"pointer\" }}><X size={14} /></button>\n      </motion.div>\n    );\n  }\n\n  return null;\n}\n\n// Usage limit progress bar — shown when approaching limits\nexport function UsageBar({ feature, current, max, label }: { feature: Feature; current: number; max: number; label?: string }) {\n  const pct      = Math.min(100, Math.round((current / max) * 100));\n  const isHigh   = pct >= 80;\n  const isFull   = pct >= 100;\n  const color    = isFull ? \"#EF4444\" : isHigh ? \"#F59E0B\" : \"#6B35E8\";\n\n  return (\n    <div>\n      <div style={{ display: \"flex\", justifyContent: \"space-between\", marginBottom: 4, fontSize: 11 }}>\n        <span style={{ color: T.muted }}>{label || feature}</span>\n        <span style={{ color: isHigh ? color : T.muted, fontWeight: isHigh ? 700 : 400 }}>\n          {current} / {max}\n        </span>\n      </div>\n      <div style={{ height: 4, borderRadius: 99, background: T.faint, overflow: \"hidden\" }}>\n        <motion.div\n          initial={{ width: 0 }}\n          animate={{ width: `${pct}%` }}\n          transition={{ duration: 0.8 }}\n          style={{ height: \"100%\", borderRadius: 99, background: color }}\n        />\n      </div>\n      {isFull && (\n        <UpgradePrompt feature={feature} requiredPlan={PLAN_REQUIREMENTS[feature]} inline />\n      )}\n    </div>\n  );\n}\n","frontend/src/components/ui/FirstSaleCelebration.tsx":"import toast from 'react-hot-toast';\n\"use client\";\nimport { useState, useEffect, useRef } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Zap, X, Share2, ArrowRight } from \"lucide-react\";\nimport Link from \"next/link\";\nimport { useTheme } from \"../layout/DashboardLayout\";\n\ninterface Props {\n  orderAmount?: number;\n  customerName?: string;\n  onDismiss: () => void;\n}\n\nfunction Particle({ x, y, color, delay }: { x: number; y: number; color: string; delay: number }) {\n  return (\n    <motion.div\n      initial={{ x: \"50%\", y: \"50%\", opacity: 1, scale: 1 }}\n      animate={{ x: `${x}%`, y: `${y}%`, opacity: 0, scale: 0.2 }}\n      transition={{ duration: 1.2 + Math.random() * 0.5, delay, ease: \"easeOut\" }}\n      style={{ position: \"absolute\", width: 8, height: 8, borderRadius: 2, background: color, pointerEvents: \"none\" }}\n    />\n  );\n}\n\nconst CONFETTI_COLORS = [\"#6B35E8\",\"#A78BFA\",\"#10B981\",\"#F59E0B\",\"#EF4444\",\"#06B6D4\",\"#EC4899\",\"#fff\"];\n\nexport default function FirstSaleCelebration({ orderAmount, customerName, onDismiss }: Props) {\n\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const T = {\n    text:   isDark ? \"#F0ECFF\"                : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\"  : \"rgba(19,13,46,0.5)\",\n    faint:  isDark ? \"rgba(240,236,255,0.25)\" : \"rgba(19,13,46,0.3)\",\n    card:   isDark ? \"#181230\" : \"#ffffff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.09)\",\n    bg:     isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const particles = Array.from({ length: 60 }, (_, i) => ({\n    id: i,\n    x:  Math.random() * 200 - 50,\n    y:  Math.random() * 200 - 50,\n    color: CONFETTI_COLORS[Math.floor(Math.random() * CONFETTI_COLORS.length)],\n    delay: Math.random() * 0.3,\n  }));\n\n  const fmt = (n: number) => new Intl.NumberFormat(\"en-NG\", { style: \"currency\", currency: \"NGN\", maximumFractionDigits: 0 }).format(n);\n\n  return (\n    <div style={{ position: \"fixed\", inset: 0, zIndex: 99999, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", padding: 16, background: \"rgba(0,0,0,0.8)\", backdropFilter: \"blur(12px)\" }}>\n      {/* Particles */}\n      <div style={{ position: \"absolute\", inset: 0, overflow: \"hidden\", pointerEvents: \"none\" }}>\n        {particles.map(p => <Particle key={p.id} {...p} />)}\n      </div>\n\n      <motion.div\n        initial={{ opacity: 0, scale: 0.7, y: 40 }}\n        animate={{ opacity: 1, scale: 1, y: 0 }}\n        transition={{ type: \"spring\", stiffness: 300, damping: 24 }}\n        style={{ position: \"relative\", zIndex: 10, width: \"100%\", maxWidth: 380, borderRadius: 28, background: T.card, border: \"1px solid rgba(107,53,232,0.3)\", overflow: \"hidden\", textAlign: \"center\", padding: \"40px 32px 32px\" }}>\n\n        {/* Glow */}\n        <div style={{ position: \"absolute\", top: -40, left: \"50%\", transform: \"translateX(-50%)\", width: 200, height: 200, borderRadius: \"50%\", background: \"radial-gradient(circle, rgba(107,53,232,0.5), transparent 70%)\", filter: \"blur(30px)\", pointerEvents: \"none\" }} />\n\n        <button onClick={onDismiss} style={{ position: \"absolute\", top: 16, right: 16, color: T.faint, background: \"none\", border: \"none\", cursor: \"pointer\" }}>\n          <X size={18} />\n        </button>\n\n        {/* Icon */}\n        <motion.div\n          animate={{ rotate: [0, -10, 10, -5, 5, 0], scale: [1, 1.1, 1] }}\n          transition={{ duration: 1, delay: 0.3 }}\n          style={{ fontSize: 56, marginBottom: 16, display: \"block\" }}>\n          🔥\n        </motion.div>\n\n        <motion.h1\n          initial={{ opacity: 0, y: 20 }}\n          animate={{ opacity: 1, y: 0 }}\n          transition={{ delay: 0.2 }}\n          style={{ fontSize: 28, fontWeight: 900, color: \"#fff\", letterSpacing: \"-1.5px\", marginBottom: 8 }}>\n          FIRST SALE!\n        </motion.h1>\n\n        <motion.div\n          initial={{ opacity: 0, y: 16 }}\n          animate={{ opacity: 1, y: 0 }}\n          transition={{ delay: 0.35 }}\n          style={{ marginBottom: 24 }}>\n          {orderAmount && (\n            <p style={{ fontSize: 32, fontWeight: 900, color: \"#10B981\", letterSpacing: \"-1px\", marginBottom: 4 }}>\n              {fmt(orderAmount)}\n            </p>\n          )}\n          <p style={{ fontSize: 14, color: T.muted, lineHeight: 1.6 }}>\n            {customerName ? `${customerName} just bought from your store.` : \"Someone just bought from your store.\"}\n            {\" \"}This is your first step to financial freedom.\n          </p>\n        </motion.div>\n\n        <motion.div\n          initial={{ opacity: 0, y: 12 }}\n          animate={{ opacity: 1, y: 0 }}\n          transition={{ delay: 0.5 }}\n          style={{ display: \"flex\", gap: 10 }}>\n          <Link href=\"/dashboard/orders\" style={{ flex: 1, textDecoration: \"none\" }}>\n            <button style={{ width: \"100%\", padding: \"12px\", borderRadius: 14, background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\", border: \"none\", color: \"#fff\", fontSize: 14, fontWeight: 700, cursor: \"pointer\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 6, boxShadow: \"0 8px 24px rgba(107,53,232,0.4)\" }}>\n              View Order <ArrowRight size={14} />\n            </button>\n          </Link>\n          <button\n            onClick={() => {\n              navigator.share?.({ title: \"I just made my first sale on DropOS! 🔥\", text: \"I launched my store and got my first sale in days. You should try DropOS!\", url: \"https://droposhq.com\" })\n                .catch(() => navigator.clipboard.writeText(\"I just made my first sale on DropOS! 🔥 Try it: https://droposhq.com\"));\n              toast?.success?.(\"Copied to share!\");\n            }}\n            style={{ padding: \"12px 14px\", borderRadius: 14, border: \"1px solid rgba(255,255,255,0.12)\", background: T.faint, color: T.text, cursor: \"pointer\" }}>\n            <Share2 size={16} />\n          </button>\n        </motion.div>\n\n        <motion.p\n          initial={{ opacity: 0 }}\n          animate={{ opacity: 1 }}\n          transition={{ delay: 0.8 }}\n          style={{ fontSize: 11, color: T.faint, marginTop: 16 }}>\n          KIRO is already working on getting you the next one\n        </motion.p>\n      </motion.div>\n    </div>\n  );\n}\n","frontend/src/components/ui/CommandPalette.tsx":"\"use client\";\nimport { useState, useEffect, useRef, useCallback } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useRouter } from \"next/navigation\";\nimport { useTheme } from \"../layout/DashboardLayout\";\nimport {\n  Search, LayoutDashboard, Package, ShoppingCart, Users, BarChart2,\n  Zap, Settings, CreditCard, Truck, Tag, Gift, Bell, Store,\n  TrendingUp, Image, FileText, Globe, ArrowRight, Command,\n} from \"lucide-react\";\n\nconst NAV_ITEMS = [\n  { label: \"Dashboard\",        href: \"/dashboard\",                    icon: LayoutDashboard,  group: \"Pages\"    },\n  { label: \"KIRO\",             href: \"/kiro\",               icon: Zap,              group: \"Pages\"    },\n  { label: \"Products\",         href: \"/dashboard/products\",           icon: Package,          group: \"Pages\"    },\n  { label: \"Orders\",           href: \"/dashboard/orders\",             icon: ShoppingCart,     group: \"Pages\"    },\n  { label: \"Customers\",        href: \"/dashboard/customers\",          icon: Users,            group: \"Pages\"    },\n  { label: \"Analytics\",        href: \"/dashboard/analytics\",          icon: BarChart2,        group: \"Pages\"    },\n  { label: \"Image Studio\",     href: \"/dashboard/image-studio\",       icon: Image,            group: \"Pages\"    },\n  { label: \"Inventory\",        href: \"/dashboard/inventory\",          icon: Package,          group: \"Pages\"    },\n  { label: \"Shipping\",         href: \"/dashboard/shipping\",           icon: Truck,            group: \"Pages\"    },\n  { label: \"Coupons\",          href: \"/dashboard/coupons\",            icon: Tag,              group: \"Pages\"    },\n  { label: \"Flash Sales\",      href: \"/dashboard/flash-sales\",        icon: TrendingUp,       group: \"Pages\"    },\n  { label: \"Gift Cards\",       href: \"/dashboard/gift-cards\",         icon: Gift,             group: \"Pages\"    },\n  { label: \"Emails\",           href: \"/dashboard/emails\",             icon: FileText,         group: \"Pages\"    },\n  { label: \"Broadcasts\",       href: \"/dashboard/broadcasts\",         icon: Bell,             group: \"Pages\"    },\n  { label: \"Stores\",           href: \"/dashboard/stores\",             icon: Store,            group: \"Pages\"    },\n  { label: \"Billing\",          href: \"/dashboard/billing\",            icon: CreditCard,       group: \"Pages\"    },\n  { label: \"Settings\",         href: \"/dashboard/settings\",           icon: Settings,         group: \"Pages\"    },\n  { label: \"Customize Store\",  href: \"/dashboard/customize\",          icon: Globe,            group: \"Pages\"    },\n  { label: \"Top Products\",     href: \"/dashboard/top-products\",       icon: TrendingUp,       group: \"Pages\"    },\n  { label: \"Affiliates\",       href: \"/dashboard/affiliates\",         icon: Users,            group: \"Pages\"    },\n  // KIRO quick prompts\n  { label: \"Ask KIRO: Sales today\",           href: \"/kiro?q=What+are+my+sales+today%3F\",           icon: Zap, group: \"Ask KIRO\" },\n  { label: \"Ask KIRO: Write TikTok script\",   href: \"/kiro?q=Write+a+TikTok+script+for+my+best+product\", icon: Zap, group: \"Ask KIRO\" },\n  { label: \"Ask KIRO: Trending products\",     href: \"/kiro?q=What+products+are+trending+right+now%3F\", icon: Zap, group: \"Ask KIRO\" },\n  { label: \"Ask KIRO: Revenue forecast\",      href: \"/kiro?q=Forecast+my+revenue+for+next+30+days\",  icon: Zap, group: \"Ask KIRO\" },\n  { label: \"Ask KIRO: Improve my store\",      href: \"/kiro?q=How+can+I+improve+my+store+score%3F\",   icon: Zap, group: \"Ask KIRO\" },\n];\n\nexport default function CommandPalette() {\n\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const T = {\n    text:   isDark ? \"#F0ECFF\"                : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\"  : \"rgba(19,13,46,0.5)\",\n    faint:  isDark ? \"rgba(240,236,255,0.25)\" : \"rgba(19,13,46,0.3)\",\n    card:   isDark ? \"#181230\" : \"#ffffff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.09)\",\n    bg:     isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const [open,  setOpen]  = useState(false);\n  const [query, setQuery] = useState(\"\");\n  const [sel,   setSel]   = useState(0);\n  const router  = useRouter();\n  const inputRef = useRef<HTMLInputElement>(null);\n\n  // Open on Cmd+K / Ctrl+K\n  useEffect(() => {\n    const handler = (e: KeyboardEvent) => {\n      if ((e.metaKey || e.ctrlKey) && e.key === \"k\") {\n        e.preventDefault();\n        setOpen(o => !o);\n        setQuery(\"\");\n        setSel(0);\n      }\n      if (e.key === \"Escape\") setOpen(false);\n    };\n    window.addEventListener(\"keydown\", handler);\n    return () => window.removeEventListener(\"keydown\", handler);\n  }, []);\n\n  useEffect(() => {\n    if (open) setTimeout(() => inputRef.current?.focus(), 50);\n  }, [open]);\n\n  const filtered = query.trim()\n    ? NAV_ITEMS.filter(i => i.label.toLowerCase().includes(query.toLowerCase()))\n    : NAV_ITEMS.slice(0, 12);\n\n  const groups = filtered.reduce<Record<string, typeof NAV_ITEMS>>((acc, item) => {\n    if (!acc[item.group]) acc[item.group] = [];\n    acc[item.group].push(item);\n    return acc;\n  }, {});\n\n  const flat = Object.values(groups).flat();\n\n  const navigate = useCallback((href: string) => {\n    setOpen(false);\n    setQuery(\"\");\n    router.push(href);\n  }, [router]);\n\n  useEffect(() => {\n    const handler = (e: KeyboardEvent) => {\n      if (!open) return;\n      if (e.key === \"ArrowDown\") { e.preventDefault(); setSel(s => Math.min(s + 1, flat.length - 1)); }\n      if (e.key === \"ArrowUp\")   { e.preventDefault(); setSel(s => Math.max(s - 1, 0)); }\n      if (e.key === \"Enter\" && flat[sel]) navigate(flat[sel].href);\n    };\n    window.addEventListener(\"keydown\", handler);\n    return () => window.removeEventListener(\"keydown\", handler);\n  }, [open, sel, flat, navigate]);\n\n  return (\n    <>\n      {/* Trigger hint */}\n      <button\n        onClick={() => setOpen(true)}\n        className=\"hidden md:flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs transition-all hover:opacity-80\"\n        style={{ background: T.faint, border: \"1px solid rgba(255,255,255,0.08)\", color: T.faint }}>\n        <Search size={11} />\n        <span>Search</span>\n        <div className=\"flex items-center gap-0.5 ml-1\">\n          <kbd style={{ fontSize: 9, padding: \"1px 4px\", borderRadius: 4, background: T.faint, color: T.faint, fontFamily: \"system-ui\" }}>⌘</kbd>\n          <kbd style={{ fontSize: 9, padding: \"1px 4px\", borderRadius: 4, background: T.faint, color: T.faint, fontFamily: \"system-ui\" }}>K</kbd>\n        </div>\n      </button>\n\n      <AnimatePresence>\n        {open && (\n          <>\n            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}\n              onClick={() => setOpen(false)}\n              className=\"fixed inset-0 z-[9998]\" style={{ background: \"rgba(0,0,0,0.6)\", backdropFilter: \"blur(4px)\" }} />\n\n            <motion.div\n              initial={{ opacity: 0, scale: 0.96, y: -16 }}\n              animate={{ opacity: 1, scale: 1, y: 0 }}\n              exit={{ opacity: 0, scale: 0.96, y: -8 }}\n              transition={{ type: \"spring\", stiffness: 400, damping: 30 }}\n              className=\"fixed z-[9999] w-full max-w-lg left-1/2 -translate-x-1/2\"\n              style={{ top: \"15vh\" }}>\n\n              <div className=\"rounded-2xl overflow-hidden shadow-2xl\" style={{ background: T.card, border: \"1px solid rgba(107,53,232,0.3)\" }}>\n                {/* Search input */}\n                <div className=\"flex items-center gap-3 px-4 py-3.5\" style={{ borderBottom: \"1px solid rgba(255,255,255,0.06)\" }}>\n                  <Search size={16} style={{ color: T.faint, flexShrink: 0 }} />\n                  <input\n                    ref={inputRef}\n                    value={query}\n                    onChange={e => { setQuery(e.target.value); setSel(0); }}\n                    placeholder=\"Search pages, or ask KIRO...\"\n                    className=\"flex-1 bg-transparent border-none outline-none text-sm text-white placeholder-white/25\"\n                    style={{ fontFamily: \"inherit\" }}\n                  />\n                  <kbd onClick={() => setOpen(false)}\n                    style={{ fontSize: 10, padding: \"2px 6px\", borderRadius: 5, background: T.faint, color: T.faint, cursor: \"pointer\" }}>\n                    ESC\n                  </kbd>\n                </div>\n\n                {/* Results */}\n                <div style={{ maxHeight: \"min(60vh, 400px)\", overflowY: \"auto\", scrollbarWidth: \"none\" }}>\n                  {Object.entries(groups).map(([group, items]) => (\n                    <div key={group}>\n                      <p className=\"px-4 py-2 text-[10px] font-bold uppercase tracking-widest\" style={{ color: T.faint }}>\n                        {group}\n                      </p>\n                      {items.map((item, i) => {\n                        const globalIdx = flat.indexOf(item);\n                        const Icon = item.icon;\n                        const isActive = sel === globalIdx;\n                        return (\n                          <button key={item.href} onClick={() => navigate(item.href)}\n                            onMouseEnter={() => setSel(globalIdx)}\n                            className=\"w-full flex items-center gap-3 px-4 py-2.5 text-left transition-all\"\n                            style={{ background: isActive ? \"rgba(107,53,232,0.15)\" : \"transparent\", borderLeft: isActive ? \"2px solid #8B5CF6\" : \"2px solid transparent\" }}>\n                            <div className=\"w-7 h-7 rounded-lg flex items-center justify-center flex-shrink-0\" style={{ background: isActive ? \"rgba(107,53,232,0.2)\" : T.faint }}>\n                              <Icon size={13} style={{ color: isActive ? \"#A78BFA\" : T.muted }} />\n                            </div>\n                            <span className=\"text-sm font-medium\" style={{ color: isActive ? \"#fff\" : T.text }}>\n                              {item.label}\n                            </span>\n                            {isActive && <ArrowRight size={12} style={{ color: \"#8B5CF6\", marginLeft: \"auto\" }} />}\n                          </button>\n                        );\n                      })}\n                    </div>\n                  ))}\n                  {filtered.length === 0 && (\n                    <div className=\"text-center py-10\">\n                      <p className=\"text-sm\" style={{ color: T.faint }}>No results for \"{query}\"</p>\n                    </div>\n                  )}\n                </div>\n\n                {/* Footer */}\n                <div className=\"flex items-center gap-4 px-4 py-2.5\" style={{ borderTop: \"1px solid rgba(255,255,255,0.06)\" }}>\n                  {[[\"↑↓\", \"navigate\"], [\"↵\", \"open\"], [\"esc\", \"close\"]].map(([k, l]) => (\n                    <div key={k} className=\"flex items-center gap-1.5\">\n                      <kbd style={{ fontSize: 10, padding: \"1px 5px\", borderRadius: 4, background: T.faint, color: T.faint, fontFamily: \"system-ui\" }}>{k}</kbd>\n                      <span style={{ fontSize: 10, color: T.faint }}>{l}</span>\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </motion.div>\n          </>\n        )}\n      </AnimatePresence>\n    </>\n  );\n}\n","frontend/src/components/ui/MilestoneCelebration.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { api } from \"../../lib/api\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport Link from \"next/link\";\nimport { Zap, ArrowRight, X } from \"lucide-react\";\nimport { useTheme } from \"../layout/DashboardLayout\";\n\ninterface Milestone {\n  id:      string;\n  type:    \"first_sale\" | \"orders_10\" | \"revenue_100k\" | \"revenue_1m\" | \"first_product\" | \"store_complete\";\n  title:   string;\n  message: string;\n  cta?:    { label: string; href: string };\n  seen:    boolean;\n}\n\nconst MILESTONE_CONFIG: Record<string, { emoji: string; color: string; bg: string }> = {\n  first_sale:      { emoji:\"🎉\", color:\"#10B981\", bg:\"linear-gradient(135deg,#10B981,#059669)\"  },\n  orders_10:       { emoji:\"🚀\", color:\"#8B5CF6\", bg:\"linear-gradient(135deg,#6B35E8,#3D1C8A)\"  },\n  revenue_100k:    { emoji:\"💰\", color:\"#F59E0B\", bg:\"linear-gradient(135deg,#F59E0B,#D97706)\"  },\n  revenue_1m:      { emoji:\"👑\", color:\"#EC4899\", bg:\"linear-gradient(135deg,#EC4899,#BE185D)\"  },\n  first_product:   { emoji:\"📦\", color:\"#06B6D4\", bg:\"linear-gradient(135deg,#06B6D4,#0891B2)\"  },\n  store_complete:  { emoji:\"🏪\", color:\"#8B5CF6\", bg:\"linear-gradient(135deg,#6B35E8,#3D1C8A)\"  },\n};\n\nfunction Confetti() {\n  const pieces = Array.from({ length: 20 }, (_, i) => ({\n    id: i,\n    x:  Math.random() * 100,\n    color: [\"#8B5CF6\",\"#10B981\",\"#F59E0B\",\"#EC4899\",\"#06B6D4\"][i % 5],\n    delay: Math.random() * 0.5,\n    size: 6 + Math.random() * 6,\n    rotation: Math.random() * 360,\n  }));\n\n  return (\n    <div style={{ position:\"absolute\", inset:0, overflow:\"hidden\", pointerEvents:\"none\" }}>\n      {pieces.map(p => (\n        <motion.div key={p.id}\n          initial={{ x:`${p.x}%`, y:\"-10%\", rotate:p.rotation, opacity:1 }}\n          animate={{ y:\"110%\", rotate:p.rotation + 360 * 2, opacity:[1,1,0] }}\n          transition={{ duration:2.5 + Math.random(), delay:p.delay, ease:\"easeIn\" }}\n          style={{ position:\"absolute\", width:p.size, height:p.size, borderRadius:2, background:p.color }}\n        />\n      ))}\n    </div>\n  );\n}\n\nexport default function MilestoneCelebration() {\n\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const T = {\n    text:   isDark ? \"#F0ECFF\"                : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\"  : \"rgba(19,13,46,0.5)\",\n    faint:  isDark ? \"rgba(240,236,255,0.25)\" : \"rgba(19,13,46,0.3)\",\n    card:   isDark ? \"#181230\" : \"#ffffff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.09)\",\n    bg:     isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const user     = useAuthStore(s => s.user);\n  const storeId  = user?.stores?.[0]?.id;\n  const [current, setCurrent] = useState<Milestone | null>(null);\n  const [dismissed, setDismissed] = useState<string[]>([]);\n\n  const { data } = useQuery({\n    queryKey:      [\"milestones\", storeId],\n    queryFn:       () => api.get(`/milestones/${storeId}`).then(r => r.data.data || []),\n    enabled:       !!storeId,\n    refetchInterval: 60000,\n  });\n\n  useEffect(() => {\n    const milestones: Milestone[] = data || [];\n    const unseen = milestones.find(m => !m.seen && !dismissed.includes(m.id));\n    setCurrent(unseen || null);\n  }, [data, dismissed]);\n\n  const dismiss = async () => {\n    if (!current) return;\n    setDismissed(d => [...d, current.id]);\n    setCurrent(null);\n    try { await api.patch(`/milestones/${current.id}/seen`, {}); } catch {}\n  };\n\n  if (!current) return null;\n\n  const config = MILESTONE_CONFIG[current.type] || MILESTONE_CONFIG.first_sale;\n\n  return (\n    <AnimatePresence>\n      <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}\n        style={{ position:\"fixed\", inset:0, zIndex:9995, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", padding:16, background:\"rgba(0,0,0,0.65)\", backdropFilter:\"blur(8px)\" }}>\n\n        <motion.div initial={{ opacity:0, scale:0.85, y:32 }} animate={{ opacity:1, scale:1, y:0 }} exit={{ opacity:0, scale:0.9, y:16 }}\n          transition={{ type:\"spring\", stiffness:280, damping:26 }}\n          style={{ position:\"relative\", width:\"100%\", maxWidth:400, borderRadius:28, overflow:\"hidden\", background:\"T.card\", border:\"1px solid rgba(255,255,255,0.08)\", boxShadow:\"0 32px 80px rgba(0,0,0,0.5)\" }}>\n\n          <Confetti />\n\n          {/* Header gradient */}\n          <div style={{ height:6, background:config.bg }}/>\n\n          <div style={{ padding:\"32px 28px 28px\", textAlign:\"center\", position:\"relative\", zIndex:1 }}>\n            {/* Dismiss */}\n            <button onClick={dismiss}\n              style={{ position:\"absolute\", top:16, right:16, width:30, height:30, borderRadius:\"50%\", border:\"none\", background:T.faint, cursor:\"pointer\", color:\"T.muted\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n              <X size={14}/>\n            </button>\n\n            {/* Emoji */}\n            <motion.div initial={{ scale:0 }} animate={{ scale:1 }} transition={{ type:\"spring\", stiffness:300, delay:0.2 }}\n              style={{ fontSize:64, marginBottom:20, lineHeight:1, display:\"block\" }}>\n              {config.emoji}\n            </motion.div>\n\n            {/* KIRO badge */}\n            <div style={{ display:\"inline-flex\", alignItems:\"center\", gap:6, padding:\"4px 12px\", borderRadius:99, background:\"rgba(107,53,232,0.15)\", border:\"1px solid rgba(107,53,232,0.25)\", marginBottom:16 }}>\n              <Zap size={11} color=\"#A78BFA\"/>\n              <span style={{ fontSize:11, fontWeight:700, color:\"#A78BFA\" }}>KIRO</span>\n            </div>\n\n            <h2 style={{ fontSize:22, fontWeight:900, letterSpacing:\"-1px\", color:\"#fff\", marginBottom:10 }}>\n              {current.title}\n            </h2>\n            <p style={{ fontSize:14, lineHeight:1.65, color:\"T.muted\", marginBottom:24 }}>\n              {current.message}\n            </p>\n\n            {current.cta ? (\n              <div style={{ display:\"flex\", gap:10, justifyContent:\"center\", flexWrap:\"wrap\" }}>\n                <Link href={current.cta.href}>\n                  <button onClick={dismiss} style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"11px 22px\", borderRadius:14, border:\"none\", background:config.bg, color:\"#fff\", fontSize:13, fontWeight:700, cursor:\"pointer\" }}>\n                    {current.cta.label} <ArrowRight size={14}/>\n                  </button>\n                </Link>\n                <button onClick={dismiss} style={{ padding:\"11px 22px\", borderRadius:14, border:\"1px solid rgba(255,255,255,0.1)\", background:\"transparent\", color:\"T.muted\", fontSize:13, cursor:\"pointer\" }}>\n                  Close\n                </button>\n              </div>\n            ) : (\n              <button onClick={dismiss} style={{ padding:\"11px 28px\", borderRadius:14, border:\"none\", background:config.bg, color:\"#fff\", fontSize:13, fontWeight:700, cursor:\"pointer\" }}>\n                Keep going\n              </button>\n            )}\n          </div>\n        </motion.div>\n      </motion.div>\n    </AnimatePresence>\n  );\n}\n","frontend/src/components/ui/SetupChecklist.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Check, ChevronRight, X, Zap, Package, CreditCard, Share2, ShoppingBag } from \"lucide-react\";\nimport Link from \"next/link\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { api } from \"../../lib/api\";\nimport { useTheme } from \"../layout/DashboardLayout\";\n\ninterface ChecklistStep {\n  id:       string;\n  icon:     React.ElementType;\n  label:    string;\n  desc:     string;\n  href:     string;\n  points:   number;\n  check:    (data: any) => boolean;\n}\n\nconst STEPS: ChecklistStep[] = [\n  {\n    id:     \"store\",\n    icon:   ShoppingBag,\n    label:  \"Create your store\",\n    desc:   \"Give your store a name and pick a theme\",\n    href:   \"/dashboard/stores\",\n    points: 20,\n    check:  d => !!(d?.stores?.[0]?.name),\n  },\n  {\n    id:     \"product\",\n    icon:   Package,\n    label:  \"Add your first product\",\n    desc:   \"Add at least one product to your store\",\n    href:   \"/dashboard/products\",\n    points: 20,\n    check:  d => (d?.productCount || 0) > 0,\n  },\n  {\n    id:     \"kiro\",\n    icon:   Zap,\n    label:  \"Chat with KIRO\",\n    desc:   \"Ask KIRO to help set up your store\",\n    href:   \"/kiro\",\n    points: 20,\n    check:  d => (d?.kiroMessageCount || 0) > 0,\n  },\n  {\n    id:     \"payment\",\n    icon:   CreditCard,\n    label:  \"Connect payments\",\n    desc:   \"Set up Paystack to start receiving money\",\n    href:   \"/dashboard/settings\",\n    points: 20,\n    check:  d => !!(d?.stores?.[0]?.paystackConnected),\n  },\n  {\n    id:     \"share\",\n    icon:   Share2,\n    label:  \"Share your store\",\n    desc:   \"Send your store link to your first customer\",\n    href:   \"/dashboard/stores\",\n    points: 20,\n    check:  d => (d?.orderCount || 0) > 0,\n  },\n];\n\nexport default function SetupChecklist() {\n\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const T = {\n    text:   isDark ? \"#F0ECFF\"                : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\"  : \"rgba(19,13,46,0.5)\",\n    faint:  isDark ? \"rgba(240,236,255,0.25)\" : \"rgba(19,13,46,0.3)\",\n    card:   isDark ? \"#181230\" : \"#ffffff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.09)\",\n    bg:     isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const user    = useAuthStore(s => s.user);\n  const [dismissed, setDismissed] = useState(false);\n  const [hasShown, setHasShown]   = useState(false);\n\n  const { data } = useQuery({\n    queryKey:  [\"setup-progress\", user?.id],\n    queryFn:   () => api.get(\"/dashboard/setup-progress\").then(r => r.data.data),\n    enabled:   !!user?.id,\n    staleTime: 60000,\n  });\n\n  const progress = STEPS.filter(s => s.check(data || user)).length;\n  const total    = STEPS.length;\n  const pct      = Math.round((progress / total) * 100);\n  const allDone  = progress === total;\n\n  // Auto-dismiss when complete\n  useEffect(() => {\n    if (allDone) {\n      const t = setTimeout(() => setDismissed(true), 3000);\n      return () => clearTimeout(t);\n    }\n  }, [allDone]);\n\n  // Don't show if dismissed or all done\n  if (dismissed || allDone) return null;\n\n  // Only show for new users (< 7 days old)\n  const createdAt  = (user as any)?.createdAt ? new Date((user as any).createdAt) : new Date();\n  const daysSince  = (Date.now() - createdAt.getTime()) / (1000 * 60 * 60 * 24);\n  if (daysSince > 7) return null;\n\n  return (\n    <motion.div\n      initial={{ opacity: 0, y: -12 }}\n      animate={{ opacity: 1, y: 0 }}\n      exit={{ opacity: 0, y: -8 }}\n      style={{ borderRadius: 20, background: \"rgba(107,53,232,0.08)\", border: \"1px solid rgba(107,53,232,0.2)\", overflow: \"hidden\", marginBottom: 24 }}>\n\n      {/* Header */}\n      <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", padding: \"16px 20px 12px\" }}>\n        <div>\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 4 }}>\n            <Zap size={15} color=\"#8B5CF6\" />\n            <p style={{ fontSize: 14, fontWeight: 800, color: \"#fff\" }}>\n              {progress === 0 ? \"Let's get your store ready\" : `${progress} of ${total} done - keep going!`}\n            </p>\n          </div>\n          {/* Progress bar */}\n          <div style={{ width: 200, height: 4, borderRadius: 99, background: T.faint, overflow: \"hidden\" }}>\n            <motion.div\n              initial={{ width: 0 }}\n              animate={{ width: `${pct}%` }}\n              transition={{ duration: 0.8, ease: \"easeOut\" }}\n              style={{ height: \"100%\", borderRadius: 99, background: \"linear-gradient(90deg,#6B35E8,#A78BFA)\" }}\n            />\n          </div>\n        </div>\n        <button onClick={() => setDismissed(true)} style={{ color: T.faint, background: \"none\", border: \"none\", cursor: \"pointer\" }}>\n          <X size={15} />\n        </button>\n      </div>\n\n      {/* Steps */}\n      <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 1, background: T.faint }}>\n        {STEPS.map((step, i) => {\n          const done    = step.check(data || user);\n          const Icon    = step.icon;\n          return (\n            <Link key={step.id} href={done ? \"#\" : step.href} style={{ textDecoration: \"none\" }}>\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 10, padding: \"12px 16px\", background: done ? \"rgba(16,185,129,0.05)\" : \"rgba(6,4,13,0.5)\", transition: \"background 0.15s\", cursor: done ? \"default\" : \"pointer\" }}>\n                <div style={{ width: 28, height: 28, borderRadius: 8, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0, background: done ? \"rgba(16,185,129,0.15)\" : T.faint, border: `1px solid ${done ? \"rgba(16,185,129,0.3)\" : T.faint}` }}>\n                  {done\n                    ? <Check size={13} color=\"#10B981\" strokeWidth={3} />\n                    : <Icon size={13} color=\"T.muted\" />\n                  }\n                </div>\n                <div style={{ flex: 1, minWidth: 0 }}>\n                  <p style={{ fontSize: 12, fontWeight: done ? 500 : 600, color: done ? \"T.muted\" : T.text, textDecoration: done ? \"line-through\" : \"none\" }}>{step.label}</p>\n                  {!done && <p style={{ fontSize: 10, color: T.faint, marginTop: 1 }}>{step.desc}</p>}\n                </div>\n                {!done && <ChevronRight size={12} color={T.faint} />}\n              </div>\n            </Link>\n          );\n        })}\n      </div>\n\n      <div style={{ padding: \"10px 20px 14px\", fontSize: 11, color: T.faint, textAlign: \"center\" }}>\n        Complete all 5 steps to unlock your full store potential\n      </div>\n    </motion.div>\n  );\n}\n","frontend/src/components/ui/PushNotificationPrompt.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Bell, X, Zap } from \"lucide-react\";\nimport { api } from \"../../lib/api\";\nimport { useTheme } from \"../layout/DashboardLayout\";\n\nexport default function PushNotificationPrompt() {\n\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const T = {\n    text:   isDark ? \"#F0ECFF\"                : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\"  : \"rgba(19,13,46,0.5)\",\n    faint:  isDark ? \"rgba(240,236,255,0.25)\" : \"rgba(19,13,46,0.3)\",\n    card:   isDark ? \"#181230\" : \"#ffffff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.09)\",\n    bg:     isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const [show, setShow]     = useState(false);\n  const [status, setStatus] = useState<\"idle\"|\"requesting\"|\"done\">(\"idle\");\n\n  useEffect(() => {\n    // Show after 60 seconds if not already granted\n    if (!(\"Notification\" in window)) return;\n    if (Notification.permission !== \"default\") return;\n    const shown = localStorage.getItem(\"dropos-push-prompted\");\n    if (shown) return;\n    const t = setTimeout(() => setShow(true), 60000);\n    return () => clearTimeout(t);\n  }, []);\n\n  const request = async () => {\n    setStatus(\"requesting\");\n    try {\n      const perm = await Notification.requestPermission();\n      if (perm === \"granted\") {\n        // Register push subscription\n        if (\"serviceWorker\" in navigator) {\n          const reg = await navigator.serviceWorker.ready;\n          const sub = await reg.pushManager.subscribe({\n            userVisibleOnly: true,\n            applicationServerKey: process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY,\n          });\n          await api.post(\"/notifications/push-subscribe\", { subscription: sub });\n        }\n        localStorage.setItem(\"dropos-push-prompted\", \"granted\");\n      } else {\n        localStorage.setItem(\"dropos-push-prompted\", \"denied\");\n      }\n    } catch {\n      // VAPID key not set — just mark as prompted\n      localStorage.setItem(\"dropos-push-prompted\", \"skipped\");\n    } finally {\n      setStatus(\"done\");\n      setShow(false);\n    }\n  };\n\n  const dismiss = () => {\n    localStorage.setItem(\"dropos-push-prompted\", \"dismissed\");\n    setShow(false);\n  };\n\n  return (\n    <AnimatePresence>\n      {show && (\n        <motion.div\n          initial={{ opacity: 0, y: 20, x: 20 }}\n          animate={{ opacity: 1, y: 0, x: 0 }}\n          exit={{ opacity: 0, y: 20, x: 20 }}\n          style={{\n            position: \"fixed\", bottom: 88, right: 16, zIndex: 9990,\n            width: 300, borderRadius: 16, overflow: \"hidden\",\n            background: T.card, border: \"1px solid rgba(107,53,232,0.3)\",\n            boxShadow: \"0 16px 48px rgba(0,0,0,0.4)\",\n          }}>\n          <div style={{ padding: \"16px 16px 0\", display: \"flex\", alignItems: \"flex-start\", gap: 12 }}>\n            <div style={{ width: 36, height: 36, borderRadius: 10, background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}>\n              <Zap size={16} color=\"white\" />\n            </div>\n            <div style={{ flex: 1 }}>\n              <p style={{ fontSize: 13, fontWeight: 800, color: \"#fff\", marginBottom: 4 }}>\n                Get KIRO alerts instantly\n              </p>\n              <p style={{ fontSize: 11, color: T.muted, lineHeight: 1.5 }}>\n                New orders, low stock, and KIRO insights sent directly to your device.\n              </p>\n            </div>\n            <button onClick={dismiss} style={{ color: T.faint, background: \"none\", border: \"none\", cursor: \"pointer\" }}>\n              <X size={14} />\n            </button>\n          </div>\n          <div style={{ display: \"flex\", gap: 8, padding: 12 }}>\n            <button onClick={dismiss}\n              style={{ flex: 1, padding: \"8px\", borderRadius: 10, border: \"1px solid rgba(255,255,255,0.1)\", background: \"transparent\", color: T.muted, fontSize: 12, cursor: \"pointer\" }}>\n              Not now\n            </button>\n            <button onClick={request} disabled={status === \"requesting\"}\n              style={{ flex: 2, padding: \"8px\", borderRadius: 10, border: \"none\", background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\", color: \"#fff\", fontSize: 12, fontWeight: 700, cursor: \"pointer\", opacity: status === \"requesting\" ? 0.7 : 1 }}>\n              {status === \"requesting\" ? \"Enabling...\" : \"Enable alerts\"}\n            </button>\n          </div>\n        </motion.div>\n      )}\n    </AnimatePresence>\n  );\n}\n","frontend/src/components/ui/StoreHealthScore.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Zap, ChevronRight, Check, AlertTriangle, X } from \"lucide-react\";\nimport Link from \"next/link\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { api } from \"../../lib/api\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { useTheme } from \"../layout/DashboardLayout\";\n\ninterface HealthCheck {\n  id:      string;\n  label:   string;\n  passed:  boolean;\n  impact:  \"high\" | \"medium\" | \"low\";\n  fix?:    string;\n  href?:   string;\n}\n\nfunction deriveChecks(data: any, user: any): HealthCheck[] {\n  const store = user?.stores?.[0];\n  const products = data?.products || [];\n  const orders   = data?.orders   || [];\n\n  return [\n    { id: \"store_name\",    label: \"Store has a name\",               passed: !!store?.name,                             impact: \"high\",   href: \"/dashboard/stores\" },\n    { id: \"logo\",          label: \"Logo uploaded\",                  passed: !!store?.logo,                             impact: \"medium\", href: \"/dashboard/customize\" },\n    { id: \"products\",      label: \"At least 5 products\",            passed: (data?.productCount || 0) >= 5,            impact: \"high\",   href: \"/dashboard/products\" },\n    { id: \"images\",        label: \"Products have images\",           passed: products.filter((p: any) => p.images?.length > 0).length >= Math.min(products.length, 3), impact: \"high\", href: \"/dashboard/products\" },\n    { id: \"descriptions\",  label: \"Products have descriptions\",     passed: products.filter((p: any) => p.description?.length > 20).length >= Math.min(products.length, 3), impact: \"medium\", href: \"/dashboard/products\" },\n    { id: \"shipping\",      label: \"Shipping zones configured\",      passed: !!(data?.shippingZonesCount || 0),          impact: \"high\",   href: \"/dashboard/shipping\" },\n    { id: \"payment\",       label: \"Paystack connected\",             passed: !!store?.paystackConnected,                 impact: \"high\",   href: \"/dashboard/settings\" },\n    { id: \"domain\",        label: \"Custom domain set up\",           passed: !!store?.customDomain,                     impact: \"medium\", href: \"/dashboard/settings\" },\n    { id: \"social\",        label: \"Social links added\",             passed: !!(store?.instagramUrl || store?.whatsappNumber), impact: \"low\", href: \"/dashboard/stores\" },\n    { id: \"first_sale\",    label: \"First sale made\",                passed: (data?.orderCount || 0) > 0,               impact: \"high\",   href: \"/kiro\" },\n  ];\n}\n\nfunction scoreColor(score: number) {\n  if (score >= 80) return \"#10B981\";\n  if (score >= 60) return \"#F59E0B\";\n  return \"#EF4444\";\n}\n\nfunction scoreLabel(score: number) {\n  if (score >= 80) return \"Great\";\n  if (score >= 60) return \"Good\";\n  if (score >= 40) return \"Needs work\";\n  return \"Just starting\";\n}\n\nexport default function StoreHealthScore() {\n\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const T = {\n    text:   isDark ? \"#F0ECFF\"                : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\"  : \"rgba(19,13,46,0.5)\",\n    faint:  isDark ? \"rgba(240,236,255,0.25)\" : \"rgba(19,13,46,0.3)\",\n    card:   isDark ? \"#181230\" : \"#ffffff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.09)\",\n    bg:     isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const user = useAuthStore(s => s.user);\n  const storeId = user?.stores?.[0]?.id;\n  const [expanded, setExpanded] = useState(false);\n\n  const { data } = useQuery({\n    queryKey:  [\"health-data\", storeId],\n    queryFn:   () => api.get(\"/dashboard/setup-progress\").then(r => r.data.data),\n    enabled:   !!storeId,\n    staleTime: 120000,\n  });\n\n  const checks = deriveChecks(data || {}, user);\n  const passed  = checks.filter(c => c.passed).length;\n  const score   = Math.round((passed / checks.length) * 100);\n  const color   = scoreColor(score);\n  const failing = checks.filter(c => !c.passed && c.impact === \"high\");\n\n  // Don't show if perfect\n  if (score === 100) return null;\n\n  return (\n    <div className=\"rounded-2xl overflow-hidden mb-5\" style={{ background: T.faint, border: \"1px solid rgba(255,255,255,0.07)\" }}>\n      {/* Header */}\n      <button onClick={() => setExpanded(!expanded)} className=\"w-full flex items-center gap-4 p-4 text-left\">\n        {/* Score ring */}\n        <div className=\"relative flex-shrink-0\" style={{ width: 52, height: 52 }}>\n          <svg width=\"52\" height=\"52\" viewBox=\"0 0 52 52\">\n            <circle cx=\"26\" cy=\"26\" r=\"22\" fill=\"none\" stroke={T.faint} strokeWidth=\"4\" />\n            <circle cx=\"26\" cy=\"26\" r=\"22\" fill=\"none\" stroke={color} strokeWidth=\"4\"\n              strokeDasharray={`${(score / 100) * 138.2} 138.2`}\n              strokeLinecap=\"round\"\n              transform=\"rotate(-90 26 26)\"\n              style={{ transition: \"stroke-dasharray 0.8s ease\" }}\n            />\n          </svg>\n          <div className=\"absolute inset-0 flex flex-col items-center justify-center\">\n            <span className=\"font-black text-sm leading-none\" style={{ color }}>{score}</span>\n          </div>\n        </div>\n\n        <div className=\"flex-1 min-w-0\">\n          <div className=\"flex items-center gap-2 mb-0.5\">\n            <span className=\"font-bold text-sm text-white\">Store Health</span>\n            <span className=\"text-xs px-2 py-0.5 rounded-full font-semibold\" style={{ background: `${color}15`, color }}>{scoreLabel(score)}</span>\n          </div>\n          <p className=\"text-xs\" style={{ color: T.muted }}>\n            {passed}/{checks.length} checks passed · {failing.length > 0 ? `${failing.length} high priority issues` : \"Only minor gaps\"}\n          </p>\n        </div>\n\n        {/* KIRO fix button */}\n        <Link href=\"/kiro\" onClick={e => e.stopPropagation()}>\n          <div className=\"flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold\" style={{ background: \"rgba(107,53,232,0.12)\", color: \"#A78BFA\", border: \"1px solid rgba(107,53,232,0.2)\", whiteSpace: \"nowrap\" }}>\n            <Zap size={10} /> Ask KIRO to fix\n          </div>\n        </Link>\n\n        <ChevronRight size={14} style={{ color: T.faint, transform: expanded ? \"rotate(90deg)\" : \"rotate(0deg)\", transition: \"transform 0.2s\", flexShrink: 0 }} />\n      </button>\n\n      {/* Expanded checks */}\n      <AnimatePresence>\n        {expanded && (\n          <motion.div initial={{ height: 0 }} animate={{ height: \"auto\" }} exit={{ height: 0 }} style={{ overflow: \"hidden\" }}>\n            <div className=\"px-4 pb-4 space-y-1.5\" style={{ borderTop: \"1px solid rgba(255,255,255,0.05)\" }}>\n              {checks.map(c => (\n                <div key={c.id} className=\"flex items-center gap-3 py-2\">\n                  <div className=\"w-5 h-5 rounded-full flex items-center justify-center flex-shrink-0\"\n                    style={{ background: c.passed ? \"rgba(16,185,129,0.15)\" : c.impact === \"high\" ? \"rgba(239,68,68,0.15)\" : \"rgba(245,158,11,0.15)\" }}>\n                    {c.passed\n                      ? <Check size={10} color=\"#10B981\" strokeWidth={3} />\n                      : c.impact === \"high\"\n                        ? <AlertTriangle size={10} color=\"#EF4444\" />\n                        : <AlertTriangle size={10} color=\"#F59E0B\" />\n                    }\n                  </div>\n                  <span className=\"text-xs flex-1\" style={{ color: c.passed ? \"T.muted\" : T.text, textDecoration: c.passed ? \"line-through\" : \"none\" }}>\n                    {c.label}\n                  </span>\n                  {!c.passed && c.href && (\n                    <Link href={c.href} className=\"text-xs font-semibold\" style={{ color: \"#8B5CF6\" }}>Fix</Link>\n                  )}\n                </div>\n              ))}\n            </div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n}\n","frontend/src/app/error.tsx":"\"use client\";\nimport { useEffect } from \"react\";\n\nexport default function GlobalError({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {\n  useEffect(() => { console.error(\"[DropOS]\", error); }, [error]);\n  return (\n    <html>\n      <body style={{ margin:0, background:\"#07050F\", minHeight:\"100vh\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontFamily:\"system-ui\", padding:\"20px\" }}>\n        <div style={{ textAlign:\"center\", maxWidth:440 }}>\n          <div style={{ width:68, height:68, borderRadius:20, background:\"linear-gradient(135deg,#7C3AED,#4C1D95)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", margin:\"0 auto 20px\", boxShadow:\"0 12px 32px rgba(124,58,237,0.3)\" }}>\n            <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n          </div>\n          <p style={{ fontSize:11, fontWeight:700, color:\"#8B5CF6\", letterSpacing:\"0.15em\", margin:\"0 0 12px\", textTransform:\"uppercase\" as const }}>DropOS · Something went wrong</p>\n          <h1 style={{ fontSize:\"clamp(24px,5vw,40px)\", fontWeight:900, color:\"#fff\", letterSpacing:\"-0.04em\", margin:\"0 0 12px\", lineHeight:1.1 }}>Unexpected Error</h1>\n          <p style={{ fontSize:14, color:\"rgba(255,255,255,0.4)\", lineHeight:1.7, margin:\"0 0 28px\" }}>Something went wrong loading this page. Try again or go back to the dashboard.</p>\n          <div style={{ display:\"flex\", gap:10, justifyContent:\"center\", flexWrap:\"wrap\" }}>\n            <button onClick={reset} style={{ padding:\"11px 24px\", borderRadius:12, background:\"linear-gradient(135deg,#6B35E8,#3D1C8A)\", color:\"#fff\", fontSize:13, fontWeight:700, border:\"none\", cursor:\"pointer\", fontFamily:\"inherit\" }}>Try Again</button>\n            <button onClick={() => window.location.href=\"/dashboard\"} style={{ padding:\"11px 24px\", borderRadius:12, border:\"1px solid rgba(255,255,255,0.1)\", color:\"rgba(255,255,255,0.5)\", fontSize:13, fontWeight:600, background:\"transparent\", cursor:\"pointer\", fontFamily:\"inherit\" }}>Dashboard</button>\n          </div>\n          <p style={{ fontSize:11, color:\"rgba(255,255,255,0.15)\", marginTop:32 }}>DropOS · droposhq.com</p>\n        </div>\n      </body>\n    </html>\n  );\n}\n"};
